import{_ as t,K as i,a as p,c as l,ac as s,q as n}from"./chunks/framework.BSuaGltH.js";const v=JSON.parse('{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 6. 可直接复制的 JQL至13. 官方参考","description":"Jira 任务协作、JQL 条件与过滤器复用","frontmatter":{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 6. 可直接复制的 JQL至13. 官方参考","description":"Jira 任务协作、JQL 条件与过滤器复用","splitFrom":"tools/developer-tools/engineering/guide/jira-software.md","showdocs":{"topics":[{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"编辑器与IDE上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Jira Software 使用技巧与 JQL 搜索指南","summary":"Jira 任务协作、JQL 条件与过滤器复用","status":"active","related":[{"title":"编辑器与IDE：完整实践与解答","link":"/tools/developer-tools/engineering/practice/application","kind":"编辑器与IDE完整实践与解答","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南","link":"/tools/developer-tools/engineering/guide/jira-software","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 1. Jira 能解决什么问题至5. JQL 语句结构","link":"/tools/developer-tools/engineering/guide/jira-software-part-01","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Vim编辑与插件管理","link":"/tools/developer-tools/engineering/vim-editing-and-plugins","kind":"编辑器与IDE任务与配置","scope":"general","audience":"general"},{"title":"工作区、编辑器配置与调试","link":"/tools/developer-tools/engineering/workspace-and-debugging","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"}],"prev":{"text":"Jira Software 使用技巧与 JQL 搜索指南 · 1. Jira 能解决什么问题至5. JQL 语句结构","link":"/tools/developer-tools/engineering/guide/jira-software-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Jira Software 使用技巧与 JQL 搜索指南 · 1. Jira 能解决什么问题至5. JQL 语句结构","link":"/tools/developer-tools/engineering/guide/jira-software-part-01"},"next":false},"headers":[],"relativePath":"tools/developer-tools/engineering/guide/jira-software-part-02.md","filePath":"tools/developer-tools/engineering/guide/jira-software-part-02.md"}'),o={name:"tools/developer-tools/engineering/guide/jira-software-part-02.md"};function r(d,a,c,h,u,g){const e=i("Mermaid");return p(),l("div",null,[a[0]||(a[0]=s(`<h1 id="jira-software-使用技巧与-jql-搜索指南-·-6-可直接复制的-jql至13-官方参考" tabindex="-1">Jira Software 使用技巧与 JQL 搜索指南 · 6. 可直接复制的 JQL至13. 官方参考 <a class="header-anchor" href="#jira-software-使用技巧与-jql-搜索指南-·-6-可直接复制的-jql至13-官方参考" aria-label="Permalink to &quot;Jira Software 使用技巧与 JQL 搜索指南 · 6. 可直接复制的 JQL至13. 官方参考&quot;">​</a></h1><p><a href="/tools/developer-tools/engineering/guide/jira-software">返回分篇目录</a></p><h2 id="_6-可直接复制的-jql" tabindex="-1">6. 可直接复制的 JQL <a class="header-anchor" href="#_6-可直接复制的-jql" aria-label="Permalink to &quot;6. 可直接复制的 JQL {#_6-可直接复制的-jql}&quot;">​</a></h2><p>以下示例默认使用项目键 <code>PAY</code>。复制后请替换项目键、状态、版本、组件和自定义字段名称。</p><h3 id="_6-1-我的未完成任务" tabindex="-1">6.1 我的未完成任务 <a class="header-anchor" href="#_6-1-我的未完成任务" aria-label="Permalink to &quot;6.1 我的未完成任务 {#_6-1-我的未完成任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND assignee = currentUser()</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY priority DESC, updated DESC</span></span></code></pre></div><p>适合保存为个人每日入口。</p><h3 id="_6-2-当前-sprint-未完成任务" tabindex="-1">6.2 当前 Sprint 未完成任务 <a class="header-anchor" href="#_6-2-当前-sprint-未完成任务" aria-label="Permalink to &quot;6.2 当前 Sprint 未完成任务 {#_6-2-当前-sprint-未完成任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND sprint in openSprints()</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY rank ASC</span></span></code></pre></div><p>适合站会和 Sprint 执行检查。</p><h3 id="_6-3-backlog-中尚未估点的任务" tabindex="-1">6.3 Backlog 中尚未估点的任务 <a class="header-anchor" href="#_6-3-backlog-中尚未估点的任务" aria-label="Permalink to &quot;6.3 Backlog 中尚未估点的任务 {#_6-3-backlog-中尚未估点的任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND sprint is EMPTY</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>AND &quot;Story Points&quot; is EMPTY</span></span>
<span class="line"><span>ORDER BY rank ASC</span></span></code></pre></div><p><code>&quot;Story Points&quot;</code> 是常见自定义字段，团队实例中的名称可能不同。</p><h3 id="_6-4-最近-7-天新建的-bug" tabindex="-1">6.4 最近 7 天新建的 Bug <a class="header-anchor" href="#_6-4-最近-7-天新建的-bug" aria-label="Permalink to &quot;6.4 最近 7 天新建的 Bug {#_6-4-最近-7-天新建的-bug}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND issuetype = Bug</span></span>
<span class="line"><span>AND created &gt;= -7d</span></span>
<span class="line"><span>ORDER BY priority DESC, created DESC</span></span></code></pre></div><h3 id="_6-5-高优先级且未完成" tabindex="-1">6.5 高优先级且未完成 <a class="header-anchor" href="#_6-5-高优先级且未完成" aria-label="Permalink to &quot;6.5 高优先级且未完成 {#_6-5-高优先级且未完成}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND priority in (Highest, High)</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY priority DESC, created ASC</span></span></code></pre></div><p>按创建时间升序可以优先暴露长期未处理的问题。</p><h3 id="_6-6-已逾期且未解决" tabindex="-1">6.6 已逾期且未解决 <a class="header-anchor" href="#_6-6-已逾期且未解决" aria-label="Permalink to &quot;6.6 已逾期且未解决 {#_6-6-已逾期且未解决}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND due &lt; startOfDay()</span></span>
<span class="line"><span>AND resolution is EMPTY</span></span>
<span class="line"><span>ORDER BY due ASC</span></span></code></pre></div><h3 id="_6-7-无负责人任务" tabindex="-1">6.7 无负责人任务 <a class="header-anchor" href="#_6-7-无负责人任务" aria-label="Permalink to &quot;6.7 无负责人任务 {#_6-7-无负责人任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND assignee is EMPTY</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY priority DESC, created ASC</span></span></code></pre></div><h3 id="_6-8-本周发生过状态变化" tabindex="-1">6.8 本周发生过状态变化 <a class="header-anchor" href="#_6-8-本周发生过状态变化" aria-label="Permalink to &quot;6.8 本周发生过状态变化 {#_6-8-本周发生过状态变化}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND status CHANGED AFTER startOfWeek()</span></span>
<span class="line"><span>ORDER BY updated DESC</span></span></code></pre></div><h3 id="_6-9-进入完成状态后又被重新打开" tabindex="-1">6.9 进入完成状态后又被重新打开 <a class="header-anchor" href="#_6-9-进入完成状态后又被重新打开" aria-label="Permalink to &quot;6.9 进入完成状态后又被重新打开 {#_6-9-进入完成状态后又被重新打开}&quot;">​</a></h3><p>状态名需要替换为团队实际工作流状态：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND status CHANGED FROM Done</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY updated DESC</span></span></code></pre></div><h3 id="_6-10-指定版本尚未完成的任务" tabindex="-1">6.10 指定版本尚未完成的任务 <a class="header-anchor" href="#_6-10-指定版本尚未完成的任务" aria-label="Permalink to &quot;6.10 指定版本尚未完成的任务 {#_6-10-指定版本尚未完成的任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND fixVersion = &quot;2026.08&quot;</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY priority DESC, rank ASC</span></span></code></pre></div><h3 id="_6-11-按组件和标签筛选" tabindex="-1">6.11 按组件和标签筛选 <a class="header-anchor" href="#_6-11-按组件和标签筛选" aria-label="Permalink to &quot;6.11 按组件和标签筛选 {#_6-11-按组件和标签筛选}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND component = backend</span></span>
<span class="line"><span>AND labels in (tech-debt, performance)</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY priority DESC</span></span></code></pre></div><h3 id="_6-12-搜索标题或描述中的关键词" tabindex="-1">6.12 搜索标题或描述中的关键词 <a class="header-anchor" href="#_6-12-搜索标题或描述中的关键词" aria-label="Permalink to &quot;6.12 搜索标题或描述中的关键词 {#_6-12-搜索标题或描述中的关键词}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND text ~ &quot;timeout&quot;</span></span>
<span class="line"><span>ORDER BY updated DESC</span></span></code></pre></div><p>只搜索标题时：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND summary ~ &quot;timeout&quot;</span></span>
<span class="line"><span>ORDER BY created DESC</span></span></code></pre></div><h3 id="_6-13-找出近期没有更新的进行中任务" tabindex="-1">6.13 找出近期没有更新的进行中任务 <a class="header-anchor" href="#_6-13-找出近期没有更新的进行中任务" aria-label="Permalink to &quot;6.13 找出近期没有更新的进行中任务 {#_6-13-找出近期没有更新的进行中任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND statusCategory = &quot;In Progress&quot;</span></span>
<span class="line"><span>AND updated &lt; -3d</span></span>
<span class="line"><span>ORDER BY updated ASC</span></span></code></pre></div><p>适合识别可能阻塞或忘记更新的任务。</p><h3 id="_6-14-我创建但尚未分配的任务" tabindex="-1">6.14 我创建但尚未分配的任务 <a class="header-anchor" href="#_6-14-我创建但尚未分配的任务" aria-label="Permalink to &quot;6.14 我创建但尚未分配的任务 {#_6-14-我创建但尚未分配的任务}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>
<span class="line"><span>AND reporter = currentUser()</span></span>
<span class="line"><span>AND assignee is EMPTY</span></span>
<span class="line"><span>AND statusCategory != Done</span></span>
<span class="line"><span>ORDER BY created DESC</span></span></code></pre></div><h2 id="_7-按角色建立常用过滤器" tabindex="-1">7. 按角色建立常用过滤器 <a class="header-anchor" href="#_7-按角色建立常用过滤器" aria-label="Permalink to &quot;7. 按角色建立常用过滤器 {#_7-按角色建立常用过滤器}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>推荐过滤器</th><th>重点字段</th></tr></thead><tbody><tr><td>研发</td><td>我的未完成、待评审、长期未更新</td><td>Assignee、Status、Updated</td></tr><tr><td>测试</td><td>待测试、重新打开、版本内 Bug</td><td>Status、Fix Version、Issue Type</td></tr><tr><td>产品</td><td>未排期需求、当前 Sprint、即将发布</td><td>Sprint、Priority、Fix Version</td></tr><tr><td>项目负责人</td><td>高优先级、逾期、无人负责、阻塞</td><td>Priority、Due、Assignee、Links</td></tr></tbody></table>`,42)),n(e,{source:""}),a[1]||(a[1]=s('<h3 id="_7-1-过滤器命名建议" tabindex="-1">7.1 过滤器命名建议 <a class="header-anchor" href="#_7-1-过滤器命名建议" aria-label="Permalink to &quot;7.1 过滤器命名建议 {#_7-1-过滤器命名建议}&quot;">​</a></h3><p>采用统一命名可以减少重复建设：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[团队/项目] 用途 - 范围</span></span></code></pre></div><p>例如：</p><ul><li><code>[PAY] 当前 Sprint - 未完成</code></li><li><code>[PAY] 发布检查 - 2026.08</code></li><li><code>[个人] 我的高优先级任务</code></li></ul><h3 id="_7-2-共享过滤器前检查" tabindex="-1">7.2 共享过滤器前检查 <a class="header-anchor" href="#_7-2-共享过滤器前检查" aria-label="Permalink to &quot;7.2 共享过滤器前检查 {#_7-2-共享过滤器前检查}&quot;">​</a></h3><ul><li>查询不要依赖只有创建者可见的项目或字段。</li><li>需要“每个人看到自己的任务”时使用 <code>currentUser()</code>。</li><li>确认共享范围，避免向所有登录用户开放敏感项目结果。</li><li>修改被看板或仪表盘引用的过滤器前，先确认影响范围。</li></ul><h2 id="_8-看板快速筛选建议" tabindex="-1">8. 看板快速筛选建议 <a class="header-anchor" href="#_8-看板快速筛选建议" aria-label="Permalink to &quot;8. 看板快速筛选建议 {#_8-看板快速筛选建议}&quot;">​</a></h2><p>快速筛选适合在不改变看板基础范围的情况下，临时聚焦一类任务。</p><table tabindex="0"><thead><tr><th>名称</th><th>JQL</th></tr></thead><tbody><tr><td>只看我的</td><td><code>assignee = currentUser()</code></td></tr><tr><td>高优先级</td><td><code>priority in (Highest, High)</code></td></tr><tr><td>Bug</td><td><code>issuetype = Bug</code></td></tr><tr><td>无负责人</td><td><code>assignee is EMPTY</code></td></tr><tr><td>长期未更新</td><td><code>updated &lt; -3d AND statusCategory != Done</code></td></tr><tr><td>技术债</td><td><code>labels = tech-debt</code></td></tr></tbody></table><p>基础看板过滤器负责定义“哪些任务属于这个看板”，快速筛选只负责临时聚焦。不要把复杂的权限和项目边界都放进快速筛选。</p><h2 id="_9-常见误区与修正" tabindex="-1">9. 常见误区与修正 <a class="header-anchor" href="#_9-常见误区与修正" aria-label="Permalink to &quot;9. 常见误区与修正 {#_9-常见误区与修正}&quot;">​</a></h2><h3 id="_9-1-不会自动包含空值" tabindex="-1">9.1 <code>!=</code> 不会自动包含空值 <a class="header-anchor" href="#_9-1-不会自动包含空值" aria-label="Permalink to &quot;9.1 `!=` 不会自动包含空值 {#_9-1-不会自动包含空值}&quot;">​</a></h3><p>下面的查询不会返回未分配任务：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assignee != currentUser()</span></span></code></pre></div><p>需要显式包含空值：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assignee != currentUser() OR assignee is EMPTY</span></span></code></pre></div><p>组合其他条件时加括号：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project = PAY</span></span>\n<span class="line"><span>AND (assignee != currentUser() OR assignee is EMPTY)</span></span></code></pre></div><h3 id="_9-2-resolution-unresolved-不够稳妥" tabindex="-1">9.2 <code>resolution = Unresolved</code> 不够稳妥 <a class="header-anchor" href="#_9-2-resolution-unresolved-不够稳妥" aria-label="Permalink to &quot;9.2 `resolution = Unresolved` 不够稳妥 {#_9-2-resolution-unresolved-不够稳妥}&quot;">​</a></h3><p>查找未解决任务通常使用：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resolution is EMPTY</span></span></code></pre></div><p>工作流在关闭或重新打开任务时，应同步正确设置或清空 Resolution，否则搜索结果和报表会失真。</p><h3 id="_9-3-显示名、字段名和状态名可能变化" tabindex="-1">9.3 显示名、字段名和状态名可能变化 <a class="header-anchor" href="#_9-3-显示名、字段名和状态名可能变化" aria-label="Permalink to &quot;9.3 显示名、字段名和状态名可能变化 {#_9-3-显示名、字段名和状态名可能变化}&quot;">​</a></h3><ul><li>带空格的值或字段名使用双引号，例如 <code>&quot;Story Points&quot;</code>。</li><li>自定义字段重名时，使用 Jira 自动补全确认字段。</li><li>跨项目查询尽量使用 <code>statusCategory</code>，减少具体状态名差异。</li><li>用户字段优先选择自动补全结果，不要手工猜账号标识。</li></ul><h3 id="_9-4-order-by-不是筛选条件" tabindex="-1">9.4 <code>ORDER BY</code> 不是筛选条件 <a class="header-anchor" href="#_9-4-order-by-不是筛选条件" aria-label="Permalink to &quot;9.4 `ORDER BY` 不是筛选条件 {#_9-4-order-by-不是筛选条件}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ORDER BY priority DESC, updated DESC</span></span></code></pre></div><p>这只会改变展示顺序，不会减少结果。查询慢时，应先缩小项目、时间、Sprint 或版本范围。</p><h3 id="_9-5-文本搜索不是精确数据库匹配" tabindex="-1">9.5 文本搜索不是精确数据库匹配 <a class="header-anchor" href="#_9-5-文本搜索不是精确数据库匹配" aria-label="Permalink to &quot;9.5 文本搜索不是精确数据库匹配 {#_9-5-文本搜索不是精确数据库匹配}&quot;">​</a></h3><p><code>~</code> 使用 Jira 的文本搜索规则，分词、特殊字符和模糊匹配行为可能与直觉不同。搜索任务编号、版本、组件等结构化信息时，应优先使用对应字段。</p><h2 id="_10-jql-排查方法" tabindex="-1">10. JQL 排查方法 <a class="header-anchor" href="#_10-jql-排查方法" aria-label="Permalink to &quot;10. JQL 排查方法 {#_10-jql-排查方法}&quot;">​</a></h2><p>查询报错或结果不符合预期时，按以下顺序处理：</p>',32)),n(e,{source:""}),a[2]||(a[2]=s(`<p>实用排查步骤：</p><ol><li>只保留 <code>project = PAY</code>，确认基础范围。</li><li>每次只增加一个条件，观察结果数量。</li><li>使用编辑器自动补全选择字段、函数和值。</li><li>临时移除 <code>OR</code> 和历史查询，先验证普通条件。</li><li>用一条已知任务反向核对每个字段的真实值。</li><li>确认自己拥有浏览对应项目和任务的权限。</li></ol><h2 id="_11-团队落地建议" tabindex="-1">11. 团队落地建议 <a class="header-anchor" href="#_11-团队落地建议" aria-label="Permalink to &quot;11. 团队落地建议 {#_11-团队落地建议}&quot;">​</a></h2><h3 id="每日" tabindex="-1">每日 <a class="header-anchor" href="#每日" aria-label="Permalink to &quot;每日 {#每日}&quot;">​</a></h3><ul><li>更新自己正在处理任务的状态和剩余信息。</li><li>处理 <code>@</code> 提及、阻塞和高优先级任务。</li><li>用“我的未完成任务”过滤器作为个人工作入口。</li></ul><h3 id="每周" tabindex="-1">每周 <a class="header-anchor" href="#每周" aria-label="Permalink to &quot;每周 {#每周}&quot;">​</a></h3><ul><li>清理无负责人、长期未更新和已逾期任务。</li><li>检查 Backlog 顶部任务是否具备进入 Sprint 的条件。</li><li>关闭重复、失效或已经通过其他方式完成的任务。</li></ul><h3 id="每个-sprint" tabindex="-1">每个 Sprint <a class="header-anchor" href="#每个-sprint" aria-label="Permalink to &quot;每个 Sprint {#每个-sprint}&quot;">​</a></h3><ul><li>规划前：确认范围、估点、依赖和验收条件。</li><li>执行中：看板状态与真实进度保持一致。</li><li>结束前：检查未完成、重新打开和版本遗漏任务。</li><li>复盘时：结合过滤器和报表讨论流程问题，不只讨论个人产出。</li></ul><h2 id="_12-jql-速查卡" tabindex="-1">12. JQL 速查卡 <a class="header-anchor" href="#_12-jql-速查卡" aria-label="Permalink to &quot;12. JQL 速查卡 {#_12-jql-速查卡}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 当前用户</span></span>
<span class="line"><span>assignee = currentUser()</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 未完成</span></span>
<span class="line"><span>statusCategory != Done</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 当前 Sprint</span></span>
<span class="line"><span>sprint in openSprints()</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 最近 7 天</span></span>
<span class="line"><span>created &gt;= -7d</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 今天更新</span></span>
<span class="line"><span>updated &gt;= startOfDay()</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 空值</span></span>
<span class="line"><span>assignee is EMPTY</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 多个值</span></span>
<span class="line"><span>priority in (Highest, High)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 文本搜索</span></span>
<span class="line"><span>summary ~ &quot;timeout&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 历史变化</span></span>
<span class="line"><span>status CHANGED AFTER -7d</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 排序</span></span>
<span class="line"><span>ORDER BY priority DESC, updated DESC</span></span></code></pre></div><h2 id="_13-官方参考" tabindex="-1">13. 官方参考 <a class="header-anchor" href="#_13-官方参考" aria-label="Permalink to &quot;13. 官方参考 {#_13-官方参考}&quot;">​</a></h2><ul><li><a href="https://support.atlassian.com/jira-software-cloud/docs/use-advanced-search-with-jira-query-language-jql/" target="_blank" rel="noopener noreferrer">使用 JQL 高级搜索</a></li><li><a href="https://support.atlassian.com/jira-service-management-cloud/docs/jql-operators/" target="_blank" rel="noopener noreferrer">JQL 运算符</a></li><li><a href="https://support.atlassian.com/jira-software-cloud/docs/jql-keywords/" target="_blank" rel="noopener noreferrer">JQL 关键字</a></li><li><a href="https://support.atlassian.com/jira-software-cloud/docs/jql-functions/" target="_blank" rel="noopener noreferrer">JQL 函数</a></li><li><a href="https://support.atlassian.com/jira-software-cloud/docs/jql-optimization-recommendations/" target="_blank" rel="noopener noreferrer">JQL 查询优化建议</a></li></ul><div class="info custom-block"><p class="custom-block-title">术语变化</p><p>Atlassian 正在将部分界面术语从 “issue” 调整为 “work item”、从 “project” 调整为 “space”。现有 JQL 查询不会因此失效；如果新术语对应的字段暂时不可用，可继续使用原有字段名。</p></div>`,14))])}const k=t(o,[["render",r]]);export{v as __pageData,k as default};
